#include <queue>
#include <vector>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    double levelMedian(TreeNode* root, int level) {
        if (!root) return 0.0;
        std::queue<TreeNode*> q;
        q.push(root);
        int curLvl = 1;
        while (!q.empty()) {
            int sz = q.size();
            std::vector<int> vals;
            for (int i = 0; i < sz; ++i) {
                TreeNode* node = q.front();
                q.pop();
                vals.push_back(node->val);
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            if (curLvl == level) {
                int m = vals.size();
                if (m % 2 == 1) return vals[m / 2];
                else return (vals[m / 2 - 1] + vals[m / 2]) / 2.0;
            }
            curLvl++;
        }
        return 0.0;
    }
};

import java.util.*;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

class Solution {
    public double levelMedian(TreeNode root, int level) {
        if (root == null) return 0.0;
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        int curLvl = 1;
        while (!q.isEmpty()) {
            int sz = q.size();
            List<Integer> vals = new ArrayList<>();
            for (int i = 0; i < sz; i++) {
                TreeNode node = q.poll();
                vals.add(node.val);
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
            if (curLvl == level) {
                int m = vals.size();
                if (m % 2 == 1) return (double) vals.get(m / 2);
                else return (vals.get(m / 2 - 1) + vals.get(m / 2)) / 2.0;
            }
            curLvl++;
        }
        return 0.0;
    }
}

